function tyAlbumChapter(baseUrl, text) {
  var bu = String(baseUrl || ''), rs = String(text || ''), m;
  var album = 0, idx = 0;
  m = bu.match(/album_(?:info|chapters)\/(\d+)/);
  if (m) album = Number(m[1]);
  m = bu.match(/[?&]chapter=(\d+)/);
  if (m) idx = Number(m[1]);
  if (!album) {
    m = rs.match(/"id"\s*:\s*(\d{6,})/);
    if (m) album = Number(m[1]);
  }
  if (!album || !idx) {
    m = bu.match(/(\d{6,})-(\d+)/) || rs.match(/(\d{6,})-(\d+)/);
    if (m) { album = Number(m[1]); idx = Number(m[2]); }
  }
  if (!album || !idx) {
    m = bu.match(/\/audios\/(\d+)\/(\d+)/);
    if (m) { album = Number(m[1]); idx = Number(m[2]); }
  }
  return { album: album, idx: idx };
}
/* 换取播放地址：匿名 + 指纹 Cookie，一次请求；结果按 专辑-集 缓存 */
function tyPlayUrl(album, idx) {
  var key = 'play.' + album + '-' + idx;
  var hit = tyCacheGet(key);
  if (hit) return hit;
  var body = tyHex(tyGcmSeal(tyBytes(TY_KEY), tyBytes(tyRandHex(12)),
    tyUtf8(JSON.stringify({ album_id: album, chapter_idx: idx }))));
  var h = tyHead();
  h['Content-Type'] = 'text/plain';
  h.Cookie = tyFingerprint();
  var r = java.post(TY_SITE + '/api/play_token', body, h);
  var data = tyJson(tyBody(r), TY_KEY);
  if (!data || !data.play_url) {
    throw new Error('听友播放地址获取失败：' + ((data && data.detail) || ('HTTP ' + tyCode(r))));
  }
  tyCachePut(key, data.play_url, TY_TTL);
  return data.play_url;
}

/* ---------- 规则入口 ---------- */
/* 详情 init：统一返回专辑 JSON 字符串，供后续 JSONPath 字段使用 */
function tingAlbum(baseUrl, result) {
  var text = String(result || ''), id = tyAlbumChapter(baseUrl, text).album;
  if (text.indexOf('"payload"') < 0 && id) text = java.ajax(TY_JSON + '/album_info/' + id);
  var data = tyJson(text, tyPayloadKey(text));
  data.id = data.id || id;
  data.count = data.count || 0;
  data.statusText = tyStatus(data.status);
  data.updatedText = tyDateText(data.updated_at);
  return JSON.stringify(data);
}
/* 发现：分类接口直接返回加密 payload */
function tingExplore(result) {
  var data = tyJson(result, tyPayloadKey(result));
  var arr = (data && data.data) ? data.data : [], out = [], i, a;
  for (i = 0; i < arr.length; i++) {
    a = arr[i];
    if (!a || !a.id) continue;
    out.push({
      name: String(a.title || ''),
      author: String(a.author || ''),
      teller: String(a.teller || ''),
      cover: String(a.cover_url || ''),
      count: a.count || 0,
      status: tyStatus(a.status),
      updated: tyDateText(a.updated_at),
      url: TY_JSON + '/album_info/' + a.id
    });
  }
  return out;
}
/* 搜索：解析搜索页内联 Nuxt 数据 */
function tingSearch(result) {
  var m = String(result).match(/__NUXT_DATA__[^>]*>([\s\S]*?)<\/script>/);
  if (!m) return [];
  var arr = JSON.parse(m[1]), i, o, sr, so, list = null;
  for (i = 0; i < arr.length; i++) {
    o = arr[i];
    if (o && typeof o === 'object' && !(o instanceof Array) && o.searchResults !== undefined) {
      sr = o.searchResults;
      so = (typeof sr === 'number') ? arr[sr] : sr;
      if (so) list = (typeof so.list === 'number') ? arr[so.list] : so.list;
      break;
    }
  }
  if (!list || !list.length) return [];
  var out = [], seen = {}, j, co, id;
  for (j = 0; j < list.length; j++) {
    co = (typeof list[j] === 'number') ? arr[list[j]] : list[j];
    if (!co || typeof co !== 'object') continue;
    id = tyPick(arr, co.id);
    if (!id || seen[id]) continue;
    seen[id] = 1;
    out.push({
      name: String(tyPick(arr, co.title) || ''),
      author: String(tyPick(arr, co.author) || ''),
      cover: String(tyPick(arr, co.cover) || ''),
      intro: String(tyPick(arr, co.desc) || ''),
      kind: String(tyPick(arr, co.categoryName) || ''),
      count: tyPick(arr, co.chapterTotal) || 0,
      status: tyStatus(tyPick(arr, co.status)),
      url: TY_JSON + '/album_info/' + id
    });
  }
  return out;
}
function tyPick(arr, v) {
  if (typeof v === 'number' && v >= 0 && v < arr.length) {
    var t = arr[v];
    if (typeof t === 'string' || typeof t === 'number') return t;
  }
  return v;
}
/* 目录：章节地址用真实 https（1KB 接口 + 集号），使应用音频预加载生效 */
function tingChapters(baseUrl, result) {
  var id = tyAlbumChapter(baseUrl, result).album, text = String(result || '');
  if (text.indexOf('"payload"') < 0 && id) text = java.ajax(TY_JSON + '/album_chapters/' + id);
  var data = tyJson(text, tyPayloadKey(text));
  var arr = (data && data.chapters) ? data.chapters : [], out = [], i, c;
  for (i = 0; i < arr.length; i++) {
    c = arr[i];
    if (!c) continue;
    out.push({
      name: String(c.title || ('第' + c.index + '集')),
      url: TY_JSON + '/album_info/' + id + '?chapter=' + c.index
    });
  }
  return out;
}
/* 正文：直接换取播放地址 */
function tingPlay(baseUrl, result) {
  var ac = tyAlbumChapter(baseUrl, result);
  if (!ac.album || !ac.idx) throw new Error('听友：无法识别章节地址 ' + String(baseUrl || ''));
  return tyPlayUrl(ac.album, ac.idx);
}
